class InventoryGateway {                        // only this module knows the broker
  constructor(channel, replyQueue) {
    this.ch = channel; this.replyQueue = replyQueue; this.pending = new Map();
  }
  checkStock(sku) {                             // a method call, not messaging
    const corrId = randomUUID();
    const reply = new Promise((res, rej) => this.pending.set(corrId, { res, rej }));
    this.ch.publish('inventory', 'check', Buffer.from(sku),
                    { replyTo: this.replyQueue, correlationId: corrId });
    return reply;                               // caller awaits a domain value
  }
}
